import { seededRandom } from '../../core/xrd/synthetic';
import type { Point } from '../../core/particles/geometry';

/*
 * The example image: generated by this site, not a micrograph. Bright discs of known diameters
 * on a dark noisy background, with a data bar at the bottom holding a scale bar. It is drawn
 * with the canvas, so it is only built in the browser.
 */

export const EXAMPLE_WIDTH = 1024;
export const EXAMPLE_HEIGHT = 864;
/** The data bar is the bottom 96 pixels. */
export const EXAMPLE_BAR_HEIGHT = 96;

/** The scale bar of the example: 200 pixels long, standing for 100 nm (so 2 pixels per nm). */
export const EXAMPLE_SCALE = {
  p1: { x: 60, y: 816 } satisfies Point,
  p2: { x: 260, y: 816 } satisfies Point,
  length: 100,
  unit: 'nm' as const,
};

/** Diameters of the example particles in pixels (a diameter of 80 px is 40 nm at the example scale). */
export const EXAMPLE_DIAMETERS_PX = [60, 70, 80, 90, 100, 110, 120, 80, 90, 100, 70, 85] as const;

export const EXAMPLE_DESCRIPTION = `Synthetic example: ${EXAMPLE_DIAMETERS_PX.length} bright discs of 60 to 120 pixels diameter, drawn by this site. The scale bar is 200 pixels long and stands for 100 nm. It is not a micrograph of anything.`;

/** Draws the example image and returns it as PNG. Needs a canvas, so call it in the browser. */
export async function makeExampleImage(): Promise<Blob> {
  const canvas = document.createElement('canvas');
  canvas.width = EXAMPLE_WIDTH;
  canvas.height = EXAMPLE_HEIGHT;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('A canvas is not available in this browser.');
  const random = seededRandom(7);
  const area = EXAMPLE_HEIGHT - EXAMPLE_BAR_HEIGHT;

  const image = ctx.createImageData(EXAMPLE_WIDTH, area);
  for (let i = 0; i < EXAMPLE_WIDTH * area; i++) {
    const v = 28 + random() * 18;
    image.data[4 * i] = v;
    image.data[4 * i + 1] = v;
    image.data[4 * i + 2] = v;
    image.data[4 * i + 3] = 255;
  }
  ctx.putImageData(image, 0, 0);

  // Place discs without overlap, with a margin around each.
  const placed: { x: number; y: number; r: number }[] = [];
  for (const d of EXAMPLE_DIAMETERS_PX) {
    const r = d / 2;
    for (let attempt = 0; attempt < 500; attempt++) {
      const x = r + 20 + random() * (EXAMPLE_WIDTH - 2 * r - 40);
      const y = r + 20 + random() * (area - 2 * r - 40);
      if (placed.every((p) => Math.hypot(p.x - x, p.y - y) > p.r + r + 16)) {
        placed.push({ x, y, r });
        break;
      }
    }
  }
  for (const { x, y, r } of placed) {
    const gradient = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
    gradient.addColorStop(0, '#e8e8e8');
    gradient.addColorStop(1, '#b4b4b4');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, area, EXAMPLE_WIDTH, EXAMPLE_BAR_HEIGHT);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(EXAMPLE_SCALE.p1.x, EXAMPLE_SCALE.p1.y);
  ctx.lineTo(EXAMPLE_SCALE.p2.x, EXAMPLE_SCALE.p2.y);
  ctx.moveTo(EXAMPLE_SCALE.p1.x, EXAMPLE_SCALE.p1.y - 10);
  ctx.lineTo(EXAMPLE_SCALE.p1.x, EXAMPLE_SCALE.p1.y + 10);
  ctx.moveTo(EXAMPLE_SCALE.p2.x, EXAMPLE_SCALE.p2.y - 10);
  ctx.lineTo(EXAMPLE_SCALE.p2.x, EXAMPLE_SCALE.p2.y + 10);
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.font = '24px sans-serif';
  ctx.fillText('100 nm', EXAMPLE_SCALE.p2.x + 24, EXAMPLE_SCALE.p2.y + 8);
  ctx.fillText('SYNTHETIC EXAMPLE', EXAMPLE_WIDTH - 280, EXAMPLE_SCALE.p2.y + 8);

  return new Promise((resolve, reject) =>
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error('Could not build the image.'))),
      'image/png',
    ),
  );
}
